# 처음 켤 때부터 기능별 전체 시험 (연습 업무 사용) → steps3.json
# 기능마다 「해 보기 → 취소·뒤로·Esc」를 하고, 오류(예외)·남은 창·화면 잠김(body 고정)·업무 개수가 맞는지 확인
# 부분: 0 처음 켜기 · 1 새 업무 · 2 업무 가져오기 · 3 일하기 · 4 체크리스트 편집 · 5 업무 분담 창 · 6 공유 · 7 백업·복원 · 8 완료·레퍼런스
#       9 업무 관리 · 10 일정 · 11 법령·매뉴얼 · 12 서식·문서함 · 13 설정 · 14 진행상황 출력 · 15 삭제·휴지통 (업무 분담 주고받기 전체는 mk_flow_test.py)
# 실행: (tools 폴더에서) python mk_full_test.py [all | 부분 번호들, 예: 1,2] && node cdp3.mjs <index.html 경로>   (전체 약 20분)
import json, os, sys
P = ("(async()=>{try{const W=ms=>new Promise(r=>setTimeout(r,ms));"
     "const wf=()=>app.allData.workflows.find(w=>w.id===window.__w);"
     "const ix=t=>wf().checklist.findIndex(i=>i.text===t);"
     "const SC=()=>document.getElementById('focus-checklist-scroll-'+window.__w);"
     "const row=i=>document.querySelector('.checklist-card[data-workflow-id=\"'+window.__w+'\"][data-index=\"'+i+'\"]');"
     "const menu=()=>document.getElementById('checklistItemMenu');"
     "const toast=()=>{const t=document.getElementById('toast');return t&&t.classList.contains('show')?document.getElementById('toastMessage').textContent.replace(/\\s+/g,' ').trim().slice(0,90):'-'};"
     "const undoBtn=()=>document.querySelector('#toastMessage .toast-undo-btn');"
     "const mods=()=>[...document.querySelectorAll('.modal.show,[id^=\"aiGuideModal_\"],#cimOverlay')].filter(m=>m.getClientRects().length).map(m=>m.id||m.className.split(' ').slice(0,2).join('.')).join(',')||'없음';"
     "const nWf=()=>app.allData.workflows.filter(w=>!w.isDeleted&&!w.isDraft).length;"
     "const st=()=>' ‖ 창='+mods()+' · 몸고정='+(document.body.style.position==='fixed'?'예':'아니오')+' · 업무='+nWf()+' · 오류='+(window.__errs.splice(0).join(' / ')||'없음');"
     "const btnT=(root,t)=>[...(root||document).querySelectorAll('button,.mi,[role=button]')].find(b=>b.offsetParent&&b.textContent.replace(/\\s+/g,' ').trim().includes(t));"
     "const vis=el=>!!(el&&el.getClientRects().length&&getComputedStyle(el).visibility!=='hidden');"
     "const choice=()=>[...document.querySelectorAll('.modal.show')].find(m=>m.querySelector('button[data-choice]'));"
     "const choiceTxt=()=>{const c=choice();return c?c.textContent.replace(/\\s+/g,' ').trim().slice(0,90):'-'};")
E = "}catch(e){return 'ERR '+e.message+' '+(e.stack||'').split('\\n')[1]+' ‖ 오류='+(window.__errs||[]).splice(0).join(' / ')}})()"
def J(b): return P + b + E
S = []
def step(label, body): S.append({"label": label, "js": J(body)})
def pt(expr, dx="Math.min(14,b.width/2)"): S.append({"pt": True, "js": J("let el=null;try{el=" + expr + ";}catch(e){}if(!el){window.__errs.push('대상 없음: " + expr.replace('"', "'").replace("'", "")[:50] + "');return JSON.stringify([2,2]);}el.scrollIntoView({block:'nearest'});await W(150);const b=el.getBoundingClientRect();return JSON.stringify([b.left+" + dx + ",b.top+b.height/2])")})
def click(expr): pt(expr); S.append({"clickpt": 1})
def dbl(expr): pt(expr); S.append({"clickpt": 2})
def rclick(expr): pt(expr); S.append({"rclickpt": 1})
def key(k, vk, mods=0, ktext=None):
    d = {"key": k, "vk": vk, "mods": mods}
    if ktext: d["ktext"] = ktext
    S.append(d)
def esc(): key("Escape", 27)
def text(t): S.append({"text": t})
def shot(n): S.append({"shot": "full_" + n + ".png"})

parts = set(sys.argv[1].split(',')) if len(sys.argv) > 1 and sys.argv[1] != 'all' else None
def on(p): return parts is None or p in parts

# ───────── 0. 처음 켜기 ─────────
step("0-0 준비(오류 모으기·저장 가로채기)",
     "window.__errs=[];window.addEventListener('error',e=>window.__errs.push('EXC '+e.message));window.addEventListener('unhandledrejection',e=>window.__errs.push('REJ '+(e.reason&&e.reason.message||e.reason)));"
     "const ce=console.error;console.error=(...a)=>{window.__errs.push('ERR '+a.map(x=>x&&x.message||String(x)).join(' ').slice(0,120));ce(...a)};"
     "window.__dl=[];const od=app._downloadJsonFile.bind(app);app._downloadJsonFile=(o,n)=>{window.__dl.push({n,o})};app._saveFileWithPicker=async(b,n)=>{window.__dl.push({n,blob:b});return true};"
     "const oc=HTMLAnchorElement.prototype.click;HTMLAnchorElement.prototype.click=function(){if(this.download){window.__dl.push({n:this.download,href:this.href});return}return oc.call(this)};"
     "window.__confirmAns=true;window.confirm=m=>{window.__lastConfirm=String(m).slice(0,80);return window.__confirmAns};window.alert=m=>{window.__lastAlert=String(m).slice(0,80)};"
     "localStorage.setItem('deadlineNotifyMode','off');app.checkBackupReminder=()=>{};"
     "return '환영 창='+vis(document.getElementById('welcomeModal'))+' · 업무='+nWf()+' · 업무 없음 안내='+!!document.querySelector('.welcome-empty')+st()")
shot("00_welcome")
if on('0'):
    esc()
    step("0-1 환영 창 Esc", "await W(300);return '환영 창 남음='+vis(document.getElementById('welcomeModal'))+st()")
    step("0-2 환영 창 다시 띄우기(시험용) → 이름 없이 [시작하기]", "localStorage.removeItem('welcomeShown');document.getElementById('welcomeModal')?.remove();app.checkWelcome();await W(300);document.getElementById('welcomeSave').click();await W(300);return '창 남음='+vis(document.getElementById('welcomeModal'))+' · 알림='+toast()+st()")
    click("document.getElementById('welcomeName')")
