    step("1-3b (남았으면 닫기) 다시 열기", "if(!vis(document.getElementById('manualModal')))app.openModal('manualModal');await W(400);return 'ok'")
    click("document.getElementById('manualProjectName')")
    text("시험 업무 — 취소 확인")
    key("Enter", 13)
    step("1-4 이름 Enter → ② 절차", "await W(500);return '단계='+app._nwStep()+' · 줄='+document.querySelectorAll('#checklistItems .checklist-edit-item').length+' · 초점='+(document.activeElement&&document.activeElement.tagName)+' · Tab 안내='+!!document.getElementById('nwTabTip')")
