    step("1-5 절차 입력(단계·Tab 할 일·Shift+Tab)", "await W(200);return [...document.querySelectorAll('#checklistItems .checklist-edit-item')].map(r=>(r.dataset.indent>0?'  └':'')+r.querySelector('input').value).join(' | ')")
    click("document.getElementById('nwPrev')")
    step("1-6 [이전] → ① 이름(내용 그대로?)", "await W(300);return '단계='+app._nwStep()+' · 이름='+document.getElementById('manualProjectName').value")
    click("document.getElementById('nwNext')")
    step("1-7 다시 [다음] → 절차 그대로?", "await W(300);return '단계='+app._nwStep()+' · 줄='+[...document.querySelectorAll('#checklistItems .checklist-edit-item input')].map(i=>i.value).join(',')")
    click("document.getElementById('nwNext')")
    step("1-8 ③ 업무팁·서식", "await W(400);return '단계='+app._nwStep()+' · 줄='+document.querySelectorAll('#nwMaterials .nw-mat').length+' · 임시 업무(목록 안 보임)='+app.allData.workflows.filter(w=>w.isDraft).length+st()")
    click("document.querySelector('#nwMaterials .nw-mat-btn')")
