    esc()
    step("1-10 항목 창 Esc → 새 업무 창 그대로?", "await W(500);return '항목 창='+!!document.getElementById('cimOverlay')+' · 새 업무 창='+vis(document.getElementById('manualModal'))+' · 단계='+app._nwStep()+st()")
    click("document.getElementById('nwNext')")
