    click("document.querySelector('.sidebar-newwork-btn')")
    step("1-13 다시 열기 → 「작성하던 업무가 있습니다」", "await W(500);return '묻는 창='+choiceTxt()")
    shot("12_nw_resume")
    click("btnT(choice(),'이어서 쓰기')")
