# ───────── 2. 업무 가져오기 ─────────
if on('2'):
    step("2-0 내보내기(연습 업무) 파일 만들기", "window.__dl=[];app.focusWorkflow(window.__w);await W(1200);await app.exportOrHandOver(window.__w);await W(2500);const d=window.__dl.slice(-1)[0];window.__exp=d&&d.o;if(!window.__exp&&d&&d.blob){window.__exp=JSON.parse(await d.blob.text());}app.exitFocusMode();await W(500);return '저장된 파일='+(d&&d.n)+' · 업무='+(window.__exp&&window.__exp.workflows&&window.__exp.workflows.length)+' · 알림='+toast()+st()")
    step("2-1 업무 가져오기 → 파일 넣기 → 방식 고르는 창", "const f=new File([JSON.stringify(window.__exp)],'업무.json',{type:'application/json'});app._restoreFromFile([f]);await W(800);const m=document.getElementById('packageImportChoiceModal');return '창='+!!m+' · 추천='+(m?[...m.querySelectorAll('label')].find(l=>l.textContent.includes('추천'))?.textContent.replace(/\\s+/g,' ').trim().slice(0,12):'')+st()")
