    step("2-4 다시 → 「복사하여 시작」+마감일 → [가져오기]", "const n0=nWf();const f=new File([JSON.stringify(window.__exp)],'업무.json');app._restoreFromFile([f]);await W(800);const m=document.getElementById('packageImportChoiceModal');m.querySelector('input[value=new]').click();await W(100);const dd=new Date();dd.setDate(dd.getDate()+10);document.getElementById('pkgImportDeadline').value=dd.getFullYear()+'-'+String(dd.getMonth()+1).padStart(2,'0')+'-'+String(dd.getDate()).padStart(2,'0');btnT(m,'가져오기').click();await W(2500);const w=app.allData.workflows.filter(w=>!w.isDeleted)[0];const nw=app.allData.workflows.filter(x=>!x.isDeleted&&/소모품/.test(x.title)).sort((a,b)=>b.id-a.id)[0];window.__wi=nw.id;return '늘어난 업무='+(nWf()-n0)+' · 제목='+nw.title+' · 체크된 줄='+nw.checklist.filter(i=>app.normalizeCompleted(i)).length+' · 마감='+nw.deadline+' · 알림='+toast()+st()")
    step("2-5 그대로 가져오기", "const n0=nWf();const f=new File([JSON.stringify(window.__exp)],'업무.json');app._restoreFromFile([f]);await W(800);const m=document.getElementById('packageImportChoiceModal');m.querySelector('input[value=asIs]').click();btnT(m,'가져오기').click();await W(2500);const nw=app.allData.workflows.filter(x=>!x.isDeleted&&/소모품/.test(x.title)).sort((a,b)=>b.id-a.id)[0];return '늘어난 업무='+(nWf()-n0)+' · 제목='+nw.title+' · 체크된 줄='+nw.checklist.filter(i=>app.normalizeCompleted(i)).length+' · 업무팁 있는 줄='+nw.checklist.filter(i=>i.tip&&i.tip.content).length+' · 알림='+toast()+st()")
    step("2-6 잘못된 파일(json 아님) 넣기", "const f=new File(['이건 json이 아님'],'x.json');app._restoreFromFile([f]);await W(800);return '알림='+toast()+st()")
    step("2-7 엉뚱한 json 넣기", "const f=new File([JSON.stringify({a:1})],'x.json');app._restoreFromFile([f]);await W(1200);return '알림='+toast()+st()")
